// =============================================================================
// js/data/talents.js
// TALENTS — GAME TABLES
// =============================================================================
//
// WHAT'S IN HERE
//   Game tables: plain data, no logic. The talent catalog (TALENTS_DB).
//
// KEY NAMES (so you can search for them)
//   tables and state: TALENTS_DB
//
// WHERE IT CAME FROM
//   Gathered from js/rules/25-citation-helpers-feats-talents-db.js when the
//   code was regrouped by topic and page. Each function and table moved
//   whole and unchanged, with the comments above it, including the original
//   version notes.
//
// LOAD ORDER
//   Loaded after js/core/ and the catalogs in js/data/catalogs/, before any
//   logic. Any code here that runs while the page loads (a few table fix-
//   ups) only uses tables loaded before it; battery/_check_load_order.mjs
//   checks that.
// =============================================================================

// TALENT DATABASE — v8.2.0: 75 talents hand-extracted from the DxD20 Hero's Handbook
// (pp. 56-72), spanning all six Hero classes and their 16 talent trees.
//
// The talent system has three tiers, captured in the `tier` field:
//   - 'Talent'            (53) — base options in each tree, free selection
//   - 'Super-Talent'      (16) — one per tree; requires the Supernatural Mutation
//                                feat plus a Mutation Point cost (mp_cost field)
//   - 'Apex Super-Talent' ( 6) — one per Hero class; requires multiple Super-Talents
//                                from that class plus a higher MP cost
//
// Entry shape: {n, family, hero_class, tree, tier, is_apex?, prereqs?, prereqs_text?, mp_cost?, d}
// Hero class talents are granted at character levels 1, 3, 5, 7, and 9.
//
// v8.5.0 Layer 1: all 55 prereq-bearing entries now use structured prereq
// types (talent / talentAny / talentTree / talentTreeAny / feat / mp /
// langCount — see the type table above checkTalentPrereqs). `prereqs_text`
// keeps the rulebook's original wording for display; the structured array is
// what the engine evaluates. Do NOT author new talents with note-typed
// prereqs — notes survive only as a non-blocking GM-verify fallback.
// MP costs (`mp_cost` + the {type:'mp'} prereqs) go live in Layer 3.
const TALENTS_DB = [

  // === Strong Hero ===
  {n:'Extreme Effort',family:'Strong Hero — Extreme Effort Tree',hero_class:'Strong Hero',tree:'Extreme Effort Tree',tier:'Talent',d:'The effort requires a move action and provides a +2 bonus on the check.'},
  {n:'Improved Extreme Effort',family:'Strong Hero — Extreme Effort Tree',hero_class:'Strong Hero',tree:'Extreme Effort Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Extreme Effort'}]],prereqs_text:'Extreme Effort',d:'The effort requires a move action and provides a +2 bonus that stacks with the bonus provided by Extreme Effort (+4 total).'},
  {n:'Advanced Extreme Effort',family:'Strong Hero — Extreme Effort Tree',hero_class:'Strong Hero',tree:'Extreme Effort Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Extreme Effort'}],[{type:'talent',name:'Improved Extreme Effort'}]],prereqs_text:'Extreme Effort, Improved Extreme Effort',d:'The effort requires a move action and provides a +2 bonus that stacks with the bonuses provided by Extreme Effort and Improved Extreme Effort (+6 total).'},
  {n:'Supreme Effort',family:'Strong Hero — Extreme Effort Tree',hero_class:'Strong Hero',tree:'Extreme Effort Tree',tier:'Super-Talent',prereqs:[[{type:'talent',name:'Extreme Effort'}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:3}]],prereqs_text:'Extreme Effort, Supernatural Mutation, 3 MP',mp_cost:3,d:'The Super-Strong Hero’s effort requires a move action, providing a +5 bonus on the check for every tier of Extreme Effort; +10 bonus if character has Improved Extreme Effort, +15 bonus if the character has Advanced Extreme Effort. During a Supreme Effort the character’s Carrying Capacity is increased by x4, and they are considered one size category larger for purposes of their natural attack damage dice, grappling, and the Jump skill.'},
  {n:'Ignore Hardness',family:'Strong Hero — Ignore Hardness Tree',hero_class:'Strong Hero',tree:'Ignore Hardness Tree',tier:'Talent',bonuses:[{type:'untyped',target:'ignoreHardness',value:2},{type:'untyped',target:'breakDC',value:1}],d:'The Strong Hero ignores 2 points of an object’s hardness, and they reduce the break DC of any object grasped in both hands by 1.'},
  {n:'Improved Ignore Hardness',family:'Strong Hero — Ignore Hardness Tree',hero_class:'Strong Hero',tree:'Ignore Hardness Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Ignore Hardness'}]],prereqs_text:'Ignore Hardness',bonuses:[{type:'untyped',target:'ignoreHardness',value:2},{type:'untyped',target:'breakDC',value:1}],d:'The Strong Hero ignores 2 additional points of an object’s hardness, and they reduce the break DC of any object grasped in both hands by an additional +1 (for a total of +2).'},
  {n:'Advanced Ignore Hardness',family:'Strong Hero — Ignore Hardness Tree',hero_class:'Strong Hero',tree:'Ignore Hardness Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Ignore Hardness'}],[{type:'talent',name:'Improved Ignore Hardness'}]],prereqs_text:'Ignore Hardness, Improved Ignore Hardness',bonuses:[{type:'untyped',target:'ignoreHardness',value:2},{type:'untyped',target:'breakDC',value:1}],d:'The Strong Hero ignores 2 additional points of an object’s hardness, and they reduce the break DC of any object grasped in both hands by an additional +1 (for a total of +3).'},
  {n:'Mangler',family:'Strong Hero — Ignore Hardness Tree',hero_class:'Strong Hero',tree:'Ignore Hardness Tree',tier:'Super-Talent',prereqs:[[{type:'talent',name:'Ignore Hardness'}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:3}]],prereqs_text:'Ignore Hardness, Supernatural Mutation, 3 MP',mp_cost:3,d:'Instead of the Ignore Hardness modifiers, the Super-Strong Hero ignores more of an object’s hardness and reduces the break DC of any object held in both hands; ignore 5 points of an object’s hardness and reduces the break DC by 2 for Ignore Hardness; ignore 10 points of hardness and break DC reduces by 5 if the character has Improved Ignore Hardness; ignore 20 points of hardness and the break DC reduces by 8 if the character has Advanced Ignore Hardness. The character’s Carrying Capacity is also increased by x4, and they are considered one size category larger for purposes of their natural attack damage dice, grappling, and the Jump skill.'},
  {n:'Melee Smash',family:'Strong Hero — Melee Smash Tree',hero_class:'Strong Hero',tree:'Melee Smash Tree',tier:'Talent',bonuses:[{type:'untyped',target:'meleeDamage',value:1}],d:'The Strong Hero receives a +1 bonus on melee damage.'},
  {n:'Improved Melee Smash',family:'Strong Hero — Melee Smash Tree',hero_class:'Strong Hero',tree:'Melee Smash Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Melee Smash'}]],prereqs_text:'Melee Smash',bonuses:[{type:'untyped',target:'meleeDamage',value:1}],d:'The Strong Hero receives an additional +1 bonus on melee damage (+2 total).'},
  {n:'Advanced Melee Smash',family:'Strong Hero — Melee Smash Tree',hero_class:'Strong Hero',tree:'Melee Smash Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Melee Smash'}],[{type:'talent',name:'Improved Melee Smash'}]],prereqs_text:'Melee Smash, Improved Melee Smash',bonuses:[{type:'untyped',target:'meleeDamage',value:1}],d:'The Strong Hero receives an additional +1 bonus on melee damage (+3 total).'},
  {n:'Super-Smash',family:'Strong Hero — Melee Smash Tree',hero_class:'Strong Hero',tree:'Melee Smash Tree',tier:'Super-Talent',prereqs:[[{type:'talent',name:'Melee Smash'}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:5}]],prereqs_text:'Melee Smash, Supernatural Mutation, 5 MP',mp_cost:5,d:'Instead of the Melee Smash modifiers, the Super-Strong Hero receives a +5 bonus to melee damage for each tier of Melee Smash; +5 damage bonus for Melee Smash; +10 bonus if the character has Improved Melee Smash; or +15 damage bonus if the character has Advanced Melee Smash. The character’s Carrying Capacity is also increased by x4, and they are considered one size category larger for purposes of their natural attack damage dice, grappling, and the Jump skill.'},
  {n:'Titanic Strength',family:'Strong Hero — Apex: Super-Strong',hero_class:'Strong Hero',tree:'Apex: Super-Strong',tier:'Apex Super-Talent',is_apex:true,prereqs:[[{type:'talentAny',names:['Supreme Effort','Mangler','Super-Smash'],count:2}],[{type:'mp',amount:9}]],prereqs_text:'Two of either Supreme Effort, Mangler, or Super-Smash, 9 MP',mp_cost:9,d:'The character gains a +10 bonus to their Strength score.'},

  // === Fast Hero ===
  {n:'Evasion',family:'Fast Hero — Defensive Tree',hero_class:'Fast Hero',tree:'Defensive Tree',tier:'Talent',d:'If the Fast Hero is exposed to any effect that normally allows a character to attempt a Reflex saving throw for half damage, the Fast Hero suffers no damage if they make a successful saving throw. Evasion can only be used when wearing light armor or no armor.'},
  {n:'Uncanny Dodge 1',family:'Fast Hero — Defensive Tree',hero_class:'Fast Hero',tree:'Defensive Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Evasion'}]],prereqs_text:'Evasion',d:'The Fast Hero retains their Dexterity bonus to AC regardless of being caught flat-footed or struck by a hidden attacker. (The hero still loses their Dexterity bonus to AC if the hero is immobilized.)'},
  {n:'Uncanny Dodge 2',family:'Fast Hero — Defensive Tree',hero_class:'Fast Hero',tree:'Defensive Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Evasion'}],[{type:'talent',name:'Uncanny Dodge 1'}]],prereqs_text:'Evasion, Uncanny Dodge 1',d:'Also known as “Improved Uncanny Dodge”, the Fast Hero can no longer be flanked; the hero can react to opponents on opposite sides of them as easily as they can react to a single attacker.'},
  {n:'Defensive Roll',family:'Fast Hero — Defensive Tree',hero_class:'Fast Hero',tree:'Defensive Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Evasion'}],[{type:'talent',name:'Uncanny Dodge 1'}]],prereqs_text:'Evasion, Uncanny Dodge 1',ap_cost:1,d:'The Fast Hero can roll with a potentially lethal attack to take less damage from it. When the Fast hero would be reduced to 0 hit points or less by damage in combat (from a ranged or melee attack), the Fast Hero can attempt to roll with the damage. A Fast Hero spends an Action Point to use this talent. Once the point is spent, the hero tries to Dodge (DC 15 + 1 per 5 damage dealt, rounding down). If the Dodge succeeds, they take only half damage. The Fast Hero must be able to react to the attack to execute a Defensive Roll; if the hero is immobilized, then they can’t use this talent. A Defensive Roll is resolved as an immediate action.'},
  {n:'Opportunist',family:'Fast Hero — Defensive Tree',hero_class:'Fast Hero',tree:'Defensive Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Evasion'}]],prereqs_text:'Evasion',ap_cost:1,d:'By spending an Action Point, the Fast Hero can make an attack of opportunity against an opponent who has just been struck for damage in melee by another character. This attack counts as the Fast Hero’s attack of opportunity for that round. Even a Fast Hero with the Combat Reflexes feat can’t use this talent more than once per round.'},
  {n:'Preternatural Reflexes',family:'Fast Hero — Defensive Tree',hero_class:'Fast Hero',tree:'Defensive Tree',tier:'Super-Talent',waivesApCost:['Defensive Roll','Opportunist'],prereqs:[[{type:'talent',name:'Evasion'}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:10}]],prereqs_text:'Evasion, Supernatural Mutation, 10 MP',mp_cost:10,d:'A Fast Hero with Preternatural Reflexes receives Improved Evasion, only taking ½ damage even on a failed Reflex save. The character also receives one free Dodge or Parry each round, declared as an immediate free action against any attack roll that they are aware of. Finally, the Fast super-hero with Preternatural Reflexes no longer needs to spend an Action Point to use Defensive Roll or Opportunist.'},
  {n:'Increased Speed',family:'Fast Hero — Increased Speed Tree',hero_class:'Fast Hero',tree:'Increased Speed Tree',tier:'Talent',bonuses:[{type:'untyped',target:'speed',value:5}],d:'The Fast Hero’s base speed increases by 5 feet.'},
  {n:'Improved Increased Speed',family:'Fast Hero — Increased Speed Tree',hero_class:'Fast Hero',tree:'Increased Speed Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Increased Speed'}]],prereqs_text:'Increased Speed',bonuses:[{type:'untyped',target:'speed',value:5}],d:'The Fast Hero’s base speed increases by 5 feet. This talent stacks with Increased Speed (10 feet total).'},
  {n:'Advanced Increased Speed',family:'Fast Hero — Increased Speed Tree',hero_class:'Fast Hero',tree:'Increased Speed Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Increased Speed'}],[{type:'talent',name:'Improved Increased Speed'}]],prereqs_text:'Increased Speed, Improved Increased Speed',bonuses:[{type:'untyped',target:'speed',value:5}],d:'The Fast Hero’s base speed increases by 5 feet. This talent stacks with Increased Speed and Improved Increased Speed (15 feet total).'},
  {n:'Hyper-Speed',family:'Fast Hero — Increased Speed Tree',hero_class:'Fast Hero',tree:'Increased Speed Tree',tier:'Super-Talent',prereqs:[[{type:'talent',name:'Increased Speed'}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:5}]],prereqs_text:'Increased Speed, Supernatural Mutation, 5 MP',mp_cost:5,bonuses:[{type:'untyped',target:'speedMult',value:2,requiresTalent:'Increased Speed'},{type:'untyped',target:'speedMult',value:5,requiresTalent:'Improved Increased Speed'},{type:'untyped',target:'speedMult',value:10,requiresTalent:'Advanced Increased Speed'}],d:'The Fast Hero multiplies their base speed depending on how many tiers of Increased Speed they possess; x2 for Increased Speed, x5 for Improved Increased Speed, x10 for Advanced Increased Speed. This is in addition to the static modifiers to base speed granted by these Talents.'},
  {n:'Lightning Fast',family:'Fast Hero — Apex: Super-Fast',hero_class:'Fast Hero',tree:'Apex: Super-Fast',tier:'Apex Super-Talent',is_apex:true,prereqs:[[{type:'talent',name:'Preternatural Reflexes'}],[{type:'talent',name:'Hyper-Speed'}],[{type:'mp',amount:5}]],prereqs_text:'Preternatural Reflexes, Hyper-Speed, 5 MP',mp_cost:5,bonuses:[{type:'untyped',target:'init',value:4}],d:'The Super-Fast Hero with Lightning Fast gets a +4 to Initiative, an additional attack at their highest attack bonus when performing a full-attack action, and an additional move action each round. The Lightning Fast Hero does not suffer from fatigue due to running if they do not run at maximum speed.'},

  // === Tough Hero ===
  {n:'Damage Reduction 1/-',family:'Tough Hero — Damage Reduction Tree',hero_class:'Tough Hero',tree:'Damage Reduction Tree',tier:'Talent',prereqs:[[{type:'talentTreeAny',trees:['Energy Resistance Tree','Unbreakable Tree']}]],prereqs_text:'One other talent from either the Energy Resistance Talent Tree or the Unbreakable Talent Tree',bonuses:[{type:'untyped',target:'dr',value:1}],d:'The Tough Hero ignores 1 point of damage from melee and ranged weapons.'},
  {n:'Damage Reduction 2/-',family:'Tough Hero — Damage Reduction Tree',hero_class:'Tough Hero',tree:'Damage Reduction Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Damage Reduction 1/-'}],[{type:'talentTreeAny',trees:['Energy Resistance Tree','Unbreakable Tree']}]],prereqs_text:'Damage Reduction 1/-, one other talent from either the Energy Resistance Talent Tree or the Unbreakable Talent Tree',bonuses:[{type:'untyped',target:'dr',value:1}],d:'The Tough Hero ignores an additional 1 point of damage from melee and ranged weapons (DR 2/- total).'},
  {n:'Damage Reduction 3/-',family:'Tough Hero — Damage Reduction Tree',hero_class:'Tough Hero',tree:'Damage Reduction Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Damage Reduction 2/-'}],[{type:'talentTreeAny',trees:['Energy Resistance Tree','Unbreakable Tree']}]],prereqs_text:'Damage Reduction 2/-, one other talent from either the Energy Resistance Talent Tree or the Unbreakable Talent Tree',bonuses:[{type:'untyped',target:'dr',value:1}],d:'The Tough Hero ignores an additional 1 point of damage from melee and ranged weapons (DR 3/- total).'},
  {n:'Bulletproof',family:'Tough Hero — Damage Reduction Tree',hero_class:'Tough Hero',tree:'Damage Reduction Tree',tier:'Super-Talent',prereqs:[[{type:'talent',name:'Damage Reduction 1/-'}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:7}]],prereqs_text:'Damage Reduction 1/-, Supernatural Mutation, 7 MP',mp_cost:7,bonuses:[{type:'untyped',target:'drMult',value:5}],d:'The Super-Tough Hero’s skin turns aside most common weapons, multiplying tiers of Damage Reduction by x5. Damage Reduction 1/- becomes Damage Reduction 5/-, Damage Reduction 2/- becomes Damage Reduction 10/-, and Damage Reduction 3/- becomes Damage Reduction 15/-.'},
  {n:'Acid Resistance',family:'Tough Hero — Energy Resistance Tree',hero_class:'Tough Hero',tree:'Energy Resistance Tree',tier:'Talent',bonuses:[{type:'untyped',target:'energyResistance:Acid',valueFrom:'conMod'}],d:'The Tough Hero ignores an amount of acid damage equal to their Constitution modifier.'},
  {n:'Cold Resistance',family:'Tough Hero — Energy Resistance Tree',hero_class:'Tough Hero',tree:'Energy Resistance Tree',tier:'Talent',bonuses:[{type:'untyped',target:'energyResistance:Cold',valueFrom:'conMod'}],d:'The Tough Hero ignores an amount of cold damage equal to their Constitution modifier.'},
  {n:'Electricity Resistance',family:'Tough Hero — Energy Resistance Tree',hero_class:'Tough Hero',tree:'Energy Resistance Tree',tier:'Talent',bonuses:[{type:'untyped',target:'energyResistance:Electricity',valueFrom:'conMod'}],d:'The Tough Hero ignores an amount of electricity damage equal to their Constitution modifier.'},
  {n:'Fire Resistance',family:'Tough Hero — Energy Resistance Tree',hero_class:'Tough Hero',tree:'Energy Resistance Tree',tier:'Talent',bonuses:[{type:'untyped',target:'energyResistance:Fire',valueFrom:'conMod'}],d:'The Tough Hero ignores an amount of fire damage equal to their Constitution modifier.'},
  {n:'Sonic/Concussion Resistance',family:'Tough Hero — Energy Resistance Tree',hero_class:'Tough Hero',tree:'Energy Resistance Tree',tier:'Talent',bonuses:[{type:'untyped',target:'energyResistance:Sonic/Concussion',valueFrom:'conMod'}],d:'The Tough Hero ignores an amount of sonic or concussion damage equal to their Constitution modifier.'},
  {n:'Energy Immunity',family:'Tough Hero — Energy Resistance Tree',hero_class:'Tough Hero',tree:'Energy Resistance Tree',tier:'Super-Talent',prereqs:[[{type:'talentTree',tree:'Energy Resistance Tree'}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:5}]],prereqs_text:'At least one type of Energy Resistance, Supernatural Mutation, 5 MP',mp_cost:5,d:'Choose another Talent from the Energy Resistance Talent Tree. The Super-Tough Hero is now immune to any energy types for which they have the Energy Resistance talent.'},
  {n:'Remain Conscious',family:'Tough Hero — Unbreakable Tree',hero_class:'Tough Hero',tree:'Unbreakable Tree',tier:'Talent',d:'The Tough Hero gains the ability to continue to perform actions when they would otherwise be considered unconscious and dying. When the Tough Hero’s hit points reach –[Constitution modifier], the hero can perform as though they were disabled, making either an attack action or a move action every round until the hero reaches –[Constitution attribute] hit points (and dies) or the hero’s hit points return to 1 or higher. The hero can choose to succumb to unconsciousness if they think that doing so might prevent them from taking more damage.'},
  {n:'Robust',family:'Tough Hero — Unbreakable Tree',hero_class:'Tough Hero',tree:'Unbreakable Tree',tier:'Talent',bonuses:[{type:'untyped',target:'hp',valueFrom:'perLevel',value:1}],d:'The Tough Hero becomes especially robust, gaining a number of hit points equal to their character level as soon as they select this talent. Thereafter, the hero gains +1 hit point with each level they gain.'},
  {n:'Second Wind',family:'Tough Hero — Unbreakable Tree',hero_class:'Tough Hero',tree:'Unbreakable Tree',tier:'Talent',ap_cost:1,d:'The Tough Hero can spend 1 Action Point as a standard action to gain a Second Wind. When the hero does this, they recover a number of hit points equal 25% of their total hit points, healing the character up to a maximum of 50% of their total hit points.'},
  {n:'Stamina',family:'Tough Hero — Unbreakable Tree',hero_class:'Tough Hero',tree:'Unbreakable Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Robust'}]],prereqs_text:'Robust',d:'The Tough Hero recovers twice as fast as normal. So, the hero recovers 2 hit points per character level per evening of rest, 2 points of temporary attribute damage per evening of rest and awakens in half the normal time after being knocked unconscious.'},
  {n:'Super-Resilient',family:'Tough Hero — Unbreakable Tree',hero_class:'Tough Hero',tree:'Unbreakable Tree',tier:'Super-Talent',prereqs:[[{type:'talentTree',tree:'Unbreakable Tree'}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:3}]],prereqs_text:'Any Talent from the Unbreakable Talent Tree, Supernatural Mutation, 3 MP',mp_cost:3,bonuses:[{type:'untyped',target:'naturalAC',valueFrom:'conMod'}],d:'The Super-Tough Hero gains a Natural AC modifier equal to their Constitution modifier. If the character has Remain Conscious, then they can operate at full efficiency until –[Constitution attribute] hit points, and they do not die until –[Constitution modifier x2] hit points. If the character has Second Wind talent, then they can spend an Action Point as an immediate action to recover 25% of their total hit points, up to a maximum of 50% of their total hit points. If the character has Stamina, then they ignore the first 2 points of attribute damage from attacks that can damage the character’s physical attribute scores (ie. Str, Dex, or Con).'},
  {n:'Nigh-Invulnerable',family:'Tough Hero — Apex: Super-Tough',hero_class:'Tough Hero',tree:'Apex: Super-Tough',tier:'Apex Super-Talent',is_apex:true,prereqs:[[{type:'talentAny',names:['Bulletproof','Energy Immunity','Super-Resilient'],count:2}],[{type:'mp',amount:5}]],prereqs_text:'Two of either Bulletproof, Energy Immunity, and/or Super-Resilient, 5 MP',mp_cost:5,bonuses:[{type:'untyped',target:'dr',value:5},{type:'untyped',target:'naturalAC',value:5}],d:'The Nigh-Invulnerable character receives an increase of +5 to any Damage Reduction (to a minimum of Damage Reduction 5/-), a +5 to their Natural AC, and gains immunity to one energy type of choice. Also, the character gets to re-roll any failed Fortitude save, including Massive Damage checks. However, the second roll stands, even if it’s worse than the first roll.'},

  // === Smart Hero ===
  {n:'Savant',family:'Smart Hero — Research Tree',hero_class:'Smart Hero',tree:'Research Tree',tier:'Talent',takeable:'multiple',bonuses:[{type:'untyped',target:'param',param_role:'skill',valueFrom:'smartLevelMin1'}],param:{param_kind:'skill',param_label:'Savant Skill',options:['Computer Use','Craft (Any)','Decipher Code','Demolitions','Disable Device','Forgery','Investigate','Knowledge (Any)','Navigate','Repair','Research','Search']},d:'Select one of the skills listed in the following paragraph. The hero must have ranks in the skill if it is “Trained Only”. The Smart Hero gets to add a bonus equal to their Smart level (minimum +1) when making checks with that skill. A Smart Hero can take this talent multiple times; each time it applies to a different skill. Computer Use, Craft (any single skill), Decipher Code, Demolitions, Disable Device, Forgery, Investigate, Knowledge (any single skill), Navigate, Repair, Research, Search.'},
  {n:'Linguist',family:'Smart Hero — Research Tree',hero_class:'Smart Hero',tree:'Research Tree',tier:'Talent',prereqs:[[{type:'langCount',min:3}]],prereqs_text:'Read/Write/Speak Language for each of three different languages',d:'With this talent, the Smart Hero becomes a master linguist. Whenever the hero encounters a new language, either spoken or written, that they do not know the Smart Hero can make an Intelligence check to determine if they can understand it. The check is made with a bonus equal to the hero’s Smart level (minimum +1). For a written language, the bonus applies to a Decipher Code check instead. The DC for the check depends on the situation: DC 15 if the language is in the same group as a language the hero has as a Read/Write/Speak Language skill; DC 20 if the language is unrelated to any other languages the hero knows; and DC 25 if the language is ancient or unique. With this special ability, a Smart Hero can glean enough meaning from a conversation or document to ascertain the basic message, but this ability in no way simulates actually being able to converse or fluently read and write in a given language. A single check covers roughly one minute of a spoken language or one page of a written language.'},
  {n:'Prodigy',family:'Smart Hero — Research Tree',hero_class:'Smart Hero',tree:'Research Tree',tier:'Super-Talent',prereqs:[[{type:'talent',name:'Savant'},{type:'talent',name:'Linguist'}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:3}]],prereqs_text:'Savant or Linguist, Supernatural Mutation, 3 MP',mp_cost:3,bonuses:[{type:'insight',target:'param',param_role:'mirror',mirrorOf:'Savant',value:4},{type:'insight',target:'skill:Computer Use',value:4,requiresTalent:'Linguist'},{type:'insight',target:'skill:Decipher Code',value:4,requiresTalent:'Linguist'}],d:'If the Smart Hero is a Savant, they receive an additional +4 insight bonus to all skills in which they are a Savant. If the character is a Linguist, then the character receives a +4 insight bonus to Computer Use and Decipher Code skill checks.'},
  {n:'Exploit Weakness',family:'Smart Hero — Strategy Tree',hero_class:'Smart Hero',tree:'Strategy Tree',tier:'Talent',prereqs:[[{type:'talentTree',tree:'Research Tree'}]],prereqs_text:'One talent from the Research Talent Tree',d:'After 1 round of combat, the Smart Hero can designate one opponent and try to find ways to gain an advantage by using brains over brawn. The Smart Hero uses a move action and makes an Intelligence check (DC 15) with a bonus equal to their Smart level (minimum +1). If the check succeeds, for the rest of the combat the Smart Hero uses their Intelligence bonus instead of either Strength or Dexterity bonus on attack rolls as the hero finds ways to outthink their opponent and notices weaknesses in their opponent’s fighting style.'},
  {n:'Plan',family:'Smart Hero — Strategy Tree',hero_class:'Smart Hero',tree:'Strategy Tree',tier:'Talent',prereqs:[[{type:'talentTree',tree:'Research Tree'}]],prereqs_text:'One talent from the Research Talent Tree',d:'Prior to an encounter the Smart Hero can develop a plan of action to handle the situation. Using this talent requires preparation; a Smart Hero can’t use this talent when surprised or otherwise unprepared for a particular situation. Creating a plan requires 1 minute. After creating the plan the Smart Hero makes an Intelligence check (DC 10) with a bonus equal to their Smart level (minimum +1). The result of the check provides the Smart Hero and allies with a circumstance bonus. A Smart Hero can’t take 10 or 20 when making this check.'},
  {n:'Trick',family:'Smart Hero — Strategy Tree',hero_class:'Smart Hero',tree:'Strategy Tree',tier:'Talent',prereqs:[[{type:'talentTree',tree:'Research Tree'}]],prereqs_text:'One talent from the Research Talent Tree',d:'The Smart Hero has the extraordinary ability to temporarily confuse a target through the use of ploy and deception. The target must have an Intelligence score of 3 or higher to be susceptible to a trick, must be within 30 feet of the hero, and must be able to hear and understand the hero. To play a trick on a target, the hero must use a full-round action and make an Intelligence check (DC 15), adding their Smart level (minimum +1) as a bonus. If the Intelligence check succeeds, the target can try to think quickly and ignore the trick. The target resists the trick by making a Will saving throw (DC 10 + Smart hero’s class level [minimum +1] + Smart hero’s Int bonus). If the saving throw fails, the target becomes dazed (unable to act, but can defend normally) for 1 round. A trick can only be played on a particular target once per encounter. After the first trick in an encounter, whether the attempt succeeds or not, that target becomes wary and immune to such ploys.'},
  {n:'Master Strategist',family:'Smart Hero — Strategy Tree',hero_class:'Smart Hero',tree:'Strategy Tree',tier:'Super-Talent',prereqs:[[{type:'talentTree',tree:'Strategy Tree'}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:7}]],prereqs_text:'Any one Talent from the Strategy Talent Tree, Supernatural Mutation, 7 MP',mp_cost:7,d:'This character has a supernatural knack for the art of war, using their resources to best advantage, anticipating their opponent’s moves, and using their opponent’s weaknesses against them. The character gets to re-roll any Intelligence check for a Strategy Tree talent (including the Master Strategist super-talent), if they wish; the second roll stands, even if it’s worse than the first roll.'},
  {n:'Supra-Genius',family:'Smart Hero — Apex: Super-Smart',hero_class:'Smart Hero',tree:'Apex: Super-Smart',tier:'Apex Super-Talent',is_apex:true,prereqs:[[{type:'talent',name:'Prodigy'}],[{type:'talent',name:'Master Strategist'}],[{type:'mp',amount:10}]],prereqs_text:'Prodigy, Master Strategist, 10 MP',mp_cost:10,d:'The Supra-Genius receives the extraordinary ability to recall any piece of information that they’ve ever been exposed to; if a Supra-Genius ever fails a Knowledge skill check, they get an immediate re-roll with an additional +4 bonus. However, the second roll stands, even if it’s worse than the first roll. The Supra-Genius Master Strategist is allowed to ready their action in regard to another creature’s action without declaring specifically what it is, akin but superior to the Master Strategist ability. Instead, the Super-Smart Hero can opt to declare what they will do after hearing any other character’s declared action, but before the target resolves the action on their initiative; change the Supra-Genius’ initiative result to the one before the target’s initiative, and resolve the Supra-Genius’ action. Then resolve the target’s previously-declared action; if the declared action becomes impossible, then the target’s action is wasted in futility, leaving the target effectively Dazed as they’re taken off-guard by the Supra-Genius’ pre-emptive action. Otherwise, both the Supra-Genius and the target resolve their actions at normal, with the change in initiative order going forward. Note that the Supra-Genius does NOT need to make an opposed Intelligence check to use this ability, unless facing off against another Supra-Genius; in the case of two Supra-Geniuses trying to use Master Strategist on one another, they make an opposed Intelligence check; the loser of the check declares their action first.'},

  // === Dedicated Hero ===
  {n:'Empathy',family:'Dedicated Hero — Empathic Tree',hero_class:'Dedicated Hero',tree:'Empathic Tree',tier:'Talent',bonuses:[{type:'untyped',target:'skill:Bluff',valueFrom:'dedicatedLevelMin1',condition:'after 1+ minute observing the target'},{type:'untyped',target:'skill:Diplomacy',valueFrom:'dedicatedLevelMin1',condition:'after 1+ minute observing the target'},{type:'untyped',target:'skill:Handle Animal',valueFrom:'dedicatedLevelMin1',condition:'after 1+ minute observing the target'},{type:'untyped',target:'skill:Intimidate',valueFrom:'dedicatedLevelMin1',condition:'after 1+ minute observing the target'},{type:'untyped',target:'skill:Perform (Any)',valueFrom:'dedicatedLevelMin1',condition:'after 1+ minute observing the target'},{type:'untyped',target:'skill:Sense Motive',valueFrom:'dedicatedLevelMin1',condition:'after 1+ minute observing the target'}],d:'The Dedicated Hero has a knack for being sensitive to the feelings and thoughts of others without having those feelings and thoughts communicated in any objectively explicit manner. This innate talent provides a bonus on checks involving interaction skills (Bluff, Diplomacy, Handle Animal, Intimidate, Perform, and Sense Motive), provided the hero spends at least 1 minute observing their target prior to making the skill check. The bonus is equal to the hero’s Dedicated level (minimum +1).'},
  {n:'Improved Aid Another',family:'Dedicated Hero — Empathic Tree',hero_class:'Dedicated Hero',tree:'Empathic Tree',tier:'Talent',takeable:'multiple',prereqs:[[{type:'talent',name:'Empathy'}]],prereqs_text:'Empathy',bonuses:[{type:'untyped',target:'aidAnother',value:1}],d:'The Dedicated Hero’s bonus on attempts to Aid Another increases by +1 on a successful Aid Another check. This talent can be selected multiple times, each time increasing the bonus by +1.'},
  {n:'Intuition',family:'Dedicated Hero — Empathic Tree',hero_class:'Dedicated Hero',tree:'Empathic Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Empathy'}]],prereqs_text:'Empathy',d:'The Dedicated Hero has an innate ability to sense trouble in the air. The Dedicated Hero can make a Will saving throw (DC 15). On a successful save, the hero gets a hunch that everything is all right, or the hero gets a bad feeling about a specific situation, based on the GM’s best guess relating to the circumstances. This talent is usable a number of times per day equal to the character’s Dedicated level (minimum 1/day).'},
  {n:'Natural Empath',family:'Dedicated Hero — Empathic Tree',hero_class:'Dedicated Hero',tree:'Empathic Tree',tier:'Super-Talent',prereqs:[[{type:'talent',name:'Empathy'}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:3}]],prereqs_text:'Empathy, Supernatural Mutation, 3 MP',mp_cost:3,d:'The Dedicated Hero has the extraordinary ability of Empathy, as the power, except it is extraordinary in nature, meaning it is not suppressed by effects that suppress magic, psionic, and/or supernatural abilities. If the character has the Improved Aid Another talent, then the bonus on attempts to Aid Another increases by an additional +1. If the character has the Intuition talent, they may use it one additional time per day.'},
  {n:'Healing Knack',family:'Dedicated Hero — Healing Tree',hero_class:'Dedicated Hero',tree:'Healing Tree',tier:'Talent',bonuses:[{type:'untyped',target:'skill:Treat Injury',value:2}],d:'The Dedicated Hero has a knack for the healing arts. The hero receives a +2 bonus on all Treat Injury skill checks.'},
  {n:'Healing Touch 1',family:'Dedicated Hero — Healing Tree',hero_class:'Dedicated Hero',tree:'Healing Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Healing Knack'}]],prereqs_text:'Healing Knack',bonuses:[{type:'untyped',target:'skill:Treat Injury',value:2,condition:'restoring damage with a medical/surgery kit'}],d:'The Dedicated Hero’s ability to restore damage with a medical kit or perform surgery with a surgery kit increases by +2 hit points.'},
  {n:'Healing Touch 2',family:'Dedicated Hero — Healing Tree',hero_class:'Dedicated Hero',tree:'Healing Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Healing Knack'}],[{type:'talent',name:'Healing Touch 1'}]],prereqs_text:'Healing Knack, Healing Touch 1',bonuses:[{type:'untyped',target:'skill:Treat Injury',value:2,condition:'restoring damage with a medical/surgery kit'}],d:'The Dedicated hero’s ability to restore damage with a medical kit or perform surgery with a surgery kit increases by +2 hit points, which stacks with Healing Touch 1 for a total of +4 hit points.'},
  {n:'Healing Hands',family:'Dedicated Hero — Healing Tree',hero_class:'Dedicated Hero',tree:'Healing Tree',tier:'Super-Talent',prereqs:[[{type:'talent',name:'Healing Knack'}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:5}]],prereqs_text:'Healing Knack, Supernatural Mutation, 5 MP',mp_cost:5,ap_cost:1,d:'The character can restore a target’s hit points up to 50% of the target’s maximum hit points. The maximum amount of damage the Dedicated Hero can heal each day is equal to the character’s Wisdom modifier times the character’s Mutant level (minimum 1), which can be used over multiple applications of Healing Hands. If the character has Healing Touch 1, then they can also Remove Paralysis as an extraordinary ability 1/day. If the character has Healing Touch 2, then they can also Remove Disease as an extraordinary ability 1/day. The Dedicated Hero with Healing Hands can spend an Action Point to replenish the amount of hit points they can heal for the day, or to activate either Remove Paralysis or Remove Disease, if available to the Hero.'},
  {n:'Skill Emphasis',family:'Dedicated Hero — Insightful Tree',hero_class:'Dedicated Hero',tree:'Insightful Tree',tier:'Talent',takeable:'multiple',bonuses:[{type:'untyped',target:'param',param_role:'skill',value:3}],param:{param_kind:'skill',param_label:'Skill'},d:'The Dedicated Hero chooses a single skill and receives a +3 bonus on all checks with that skill. This bonus does not allow the hero to make checks for a trained-only skill if the hero has no ranks in the skill.'},
  {n:'Aware',family:'Dedicated Hero — Insightful Tree',hero_class:'Dedicated Hero',tree:'Insightful Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Skill Emphasis'}]],prereqs_text:'Skill Emphasis',bonuses:[{type:'untyped',target:'skill:Listen',valueFrom:'baseWill',condition:'to avoid surprise'},{type:'untyped',target:'skill:Spot',valueFrom:'baseWill',condition:'to avoid surprise'}],d:'The Dedicated Hero is intuitively aware of their surroundings. The hero adds their base Will saving throw bonus to Listen or Spot checks to avoid surprise.'},
  {n:'Faith',family:'Dedicated Hero — Insightful Tree',hero_class:'Dedicated Hero',tree:'Insightful Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Skill Emphasis'}]],prereqs_text:'Skill Emphasis',bonuses:[{type:'untyped',target:'apRollBonus',valueFrom:'wisMod'}],d:'The Dedicated Hero has a great deal of faith. It might be faith in self, in a higher power, or in both. This unswerving belief allows the Dedicated Hero to add their Wisdom modifier to the die roll whenever the hero spends 1 Action Point to improve the result of an attack roll, skill check, saving throw, or ability check.'},
  {n:'Cool Under Pressure',family:'Dedicated Hero — Insightful Tree',hero_class:'Dedicated Hero',tree:'Insightful Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Skill Emphasis'}],[{type:'talent',name:'Faith'},{type:'talent',name:'Aware'}]],prereqs_text:'Skill Emphasis plus either Faith or Aware',d:'The Dedicated Hero selects a number of skills equal to 3 + the hero’s Wisdom modifier. When making a check with one of these skills, the Dedicated Hero can take 10 even when distracted or under duress.'},
  {n:'Uncanny Insight',family:'Dedicated Hero — Insightful Tree',hero_class:'Dedicated Hero',tree:'Insightful Tree',tier:'Super-Talent',prereqs:[[{type:'talent',name:'Skill Emphasis'}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:3}]],prereqs_text:'Skill Emphasis, Supernatural Mutation, 3 MP',mp_cost:3,d:'The Dedicated Hero’s emphasis on a skill gives them new insights into the inner workings of that skill; if the Dedicated Hero ever fails a skill check with a skill that they have Skill Emphasis for, the Dedicated Hero may re-roll the result. The hero must accept the second result, even if it’s worse than the first one. If the Dedicated Hero is Aware with Uncanny Insight, then they have the option of spending an Action Point to nullify surprise and roll initiative as normal. If the Dedicated Hero has Faith with Uncanny Insight, then they have the option of spending an Action Point to re-roll any d20 roll originally made by the Dedicated Hero, with a bonus equal to the Dedicated Hero’s Wisdom modifier. If the Dedicated Hero is Cool Under Pressure with Uncanny Insight, then they have the option of re-rolling any failed Fortitude or Will save. The hero must accept the result of the second roll, even if it’s worse than the first roll.'},
  {n:'Indomitable Will',family:'Dedicated Hero — Apex: Super-Dedicated',hero_class:'Dedicated Hero',tree:'Apex: Super-Dedicated',tier:'Apex Super-Talent',is_apex:true,prereqs:[[{type:'talentAny',names:['Natural Empath','Healing Hands','Uncanny Insight'],count:2}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:9}]],prereqs_text:'Any two of Natural Empath, Healing Hands, and/or Uncanny Insight, Supernatural Mutation, 9 MP',mp_cost:9,d:'This hero has an unassailable spirit and is thus immune to ability damage to their mental attributes (i.e., Int, Wis, Cha). Also, the character gains Mettle; any Fortitude or Will saving throws for “half” damage or “partial” effects are instead “negated” with a successful save.'},

  // === Charismatic Hero ===
  {n:'Charm',family:'Charismatic Hero — Charm Tree',hero_class:'Charismatic Hero',tree:'Charm Tree',tier:'Talent',d:'The Charismatic Hero gets a competence bonus on all Charisma-based skill checks made to influence others. The bonus is equal to the character’s Charismatic level (minimum +1). A Charismatic Hero can only use their Charm bonus on Gamemaster characters with attitudes of indifferent or better. The Charm bonus can’t be used against characters who are unfriendly or hostile.'},
  {n:'Favor',family:'Charismatic Hero — Charm Tree',hero_class:'Charismatic Hero',tree:'Charm Tree',tier:'Talent',ap_cost:1,prereqs:[[{type:'talent',name:'Charm'}]],prereqs_text:'Charm',d:'The Charismatic Hero has the ability to acquire minor aid from anyone they meet. By making a Favor check, a Charismatic Hero can gain important information without going through the time and trouble of doing a lot of research. Favors can also be used to acquire the loan of equipment or documents, or to receive other minor assistance in the course of an adventure. A Charismatic Hero spends 1 Action Point to activate this talent. To make a Favor check, roll a d20 and add the character’s Favor bonus, equal to the character’s Charismatic level (minimum +1). The GM sets the DC based on the scope of the favor being requested. The DC ranges from 10 for a simple favor to as high as 30 for formidable and highly dangerous, expensive, or illegal favors. A Charismatic Hero can’t take 10 or take 20 on this check, nor can the hero retry the check for the same (or virtually the same) favor. Favors should help advance the plot of an adventure. A favor that would enable a character to avoid an adventure altogether should always be unavailable to the character, regardless of the result of a Favor check. The GM should carefully monitor a Charismatic Hero’s use of favors to ensure that this ability isn’t abused. The success or failure of a mission typically shouldn’t hinge on the use of a favor, and getting a favor shouldn’t replace good roleplaying or the use of other skills. The GM may disallow any Favor deemed to be disruptive to the game.'},
  {n:'Captivate',family:'Charismatic Hero — Charm Tree',hero_class:'Charismatic Hero',tree:'Charm Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Charm'}],[{type:'talent',name:'Favor'}]],prereqs_text:'Charm, Favor',d:'The Charismatic Hero has the ability to temporarily beguile a target through the use of words and bearing. The target must have an Intelligence score of 3 or higher to be susceptible to a captivate attempt, must be within 30 feet of the hero, must be flat-footed or not in combat, and must be able to see, hear, and understand the hero. To Captivate a target, the hero must use an attack action and make a Charisma check (DC 15), adding their Charismatic level as a bonus. If the Charisma check succeeds, the target can try to resist. The target resists the captivation attempt by making a Will saving throw (DC 10 + Charismatic Hero’s class level [minimum +1] + Charismatic hero’s Cha bonus). If the saving throw fails, the target becomes fascinated with the hero, who becomes the target’s sole focus. The target pays no attention to anyone else for 1 round and remains flat-footed. This focusing of the target’s attention allows other characters to take actions of which the captivated target is unaware. The effect ends immediately if the target is attacked or threatened. A Charismatic hero can concentrate to keep a target captivated for additional rounds. The Charismatic Hero concentrates all their effort on the task, and the target gets to make a new Will save each round. The effect ends when the hero stops concentrating, or when the target succeeds on the save. This is a Mind-Affecting ability.'},
  {n:'Animal Magnetism',family:'Charismatic Hero — Charm Tree',hero_class:'Charismatic Hero',tree:'Charm Tree',tier:'Super-Talent',prereqs:[[{type:'talent',name:'Charm'}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:3}]],prereqs_text:'Charm, Supernatural Mutation, 3 MP',mp_cost:3,d:'The Charismatic Hero with Animal Magnetism can Charm any creature with which they can communicate, as an extraordinary ability. The target must have an Intelligence score of 1 or higher to be susceptible to a Charm attempt, must be within 30 feet of the hero, and must be able to see, hear, and understand the hero. If the hero has Favor, then they can also make a Suggestion to a Charmed target 1/day. If the hero has Captivate, then the Will save DC to resist being captivated is increased by +4.'},
  {n:'Fast-Talk',family:'Charismatic Hero — Fast-Talk Tree',hero_class:'Charismatic Hero',tree:'Fast-Talk Tree',tier:'Talent',d:'The Charismatic Hero has a way with words when attempting to con and deceive. With this talent, they apply their Charismatic level as a competence bonus on any Bluff, Diplomacy, or Gamble checks the hero makes while attempting to lie, cheat, or otherwise bend the truth.'},
  {n:'Dazzle',family:'Charismatic Hero — Fast-Talk Tree',hero_class:'Charismatic Hero',tree:'Fast-Talk Tree',tier:'Talent',takeable:'multiple',prereqs:[[{type:'talent',name:'Fast-Talk'}]],prereqs_text:'Fast-Talk',d:'The Charismatic Hero has the ability to dazzle a target through sheer force of personality, a winning smile, and fast-talking. The target must have an Intelligence score of 3 or higher to be susceptible to a dazzle attempt, must be within 30 feet of the hero, and must be able to see, hear, and understand the hero. To Dazzle a target, the hero must use an attack action and make a Charisma check (DC 15), adding their Charismatic level (minimum +1) as a bonus. If the Charisma check succeeds, the target can try to resist. The target resists the Dazzle attempt by making a Will saving throw (DC 10 + Charismatic Hero’s class level [minimum +1] + Charismatic Hero’s Cha bonus). If the save fails, the target receives a -1 penalty on attack rolls, ability checks, skill checks, and saving throws for a number of rounds equal to the character’s Charismatic level (minimum 1 round). This talent can be selected multiple times, each time worsening the Dazzled penalty by -1. This is a Mind- Affecting ability.'},
  {n:'Taunt',family:'Charismatic Hero — Fast-Talk Tree',hero_class:'Charismatic Hero',tree:'Fast-Talk Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Fast-Talk'}],[{type:'talent',name:'Dazzle'}]],prereqs_text:'Fast-Talk, Dazzle',d:'The Charismatic Hero has the ability to temporarily rattle and enrage a target through the use of insults and goading. The target must have an Intelligence score of 3 or higher to be susceptible to a Taunt, must be within 30 feet of the hero, and must be able to hear and understand the hero. To Taunt a target, the hero must use a standard action and make a Charisma check (DC 15), adding their Charismatic level (minimum +1) as a bonus. If the Charisma check succeeds, the target can try to resist. The target resists the Taunt by making a Will saving throw (DC 10 + Charismatic Hero’s class level [minimum +1] + Charismatic Hero’s Cha bonus). If the save fails, the target becomes fixated on directing their next action against the hero for the next round. This is a Mind-Affecting ability.'},
  {n:'Silver Tongue',family:'Charismatic Hero — Fast-Talk Tree',hero_class:'Charismatic Hero',tree:'Fast-Talk Tree',tier:'Super-Talent',prereqs:[[{type:'talent',name:'Fast-Talk'}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:3}]],prereqs_text:'Fast-Talk, Supernatural Mutation, 3 MP',mp_cost:3,d:'The Charismatic Hero with a Silver Tongue receives their Fast-Talk modifier to all Bluff, Diplomacy, Gamble, Gather Information, and Intimidate checks. Also, the Silver Tongue can spend an Action Point to re-roll a skill check from the above-listed skills, but the character must accept the result of the second roll, even if it’s worse than the first roll. If the Silver Tongue can Dazzle, then the Dazzled penalty becomes equal to the hero’s Charisma modifier. If the Silver Tongue can Taunt, then they can attempt to Taunt a target as a move action if they wish.'},
  {n:'Coordinate',family:'Charismatic Hero — Leadership Tree',hero_class:'Charismatic Hero',tree:'Leadership Tree',tier:'Talent',d:'The Charismatic Hero has a knack for getting people to work together. When the hero can spend a full round directing their allies and makes a Charisma check (DC 10), the hero provides any of their allies within 30 feet a +1 bonus on their attack rolls and skill checks. The bonus lasts for a number of rounds equal to the hero’s Charisma modifier. The hero can coordinate a number of allies equal to one-half their Charismatic level, rounded down (to a minimum of one ally).'},
  {n:'Inspiration',family:'Charismatic Hero — Leadership Tree',hero_class:'Charismatic Hero',tree:'Leadership Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Coordinate'}]],prereqs_text:'Coordinate',d:'The Charismatic Hero can inspire their allies, bolstering them and improving their chances of success. An ally must listen to and observe the Charismatic Hero for a full round for the inspiration to take hold, and the hero must make a Charisma check (DC 10). The effect lasts for a number of rounds equal to the hero’s Charisma modifier. An inspired ally gains a +2 morale bonus on saving throws, attack rolls, and damage rolls. A Charismatic Hero can’t inspire themselves. The hero can inspire a number of allies equal to one-half their Charismatic level, rounded down (to a minimum of one ally).'},
  {n:'Greater Inspiration',family:'Charismatic Hero — Leadership Tree',hero_class:'Charismatic Hero',tree:'Leadership Tree',tier:'Talent',prereqs:[[{type:'talent',name:'Coordinate'}],[{type:'talent',name:'Inspiration'}]],prereqs_text:'Coordinate, Inspiration',d:'The Charismatic Hero can inspire their allies to even greater heights, bolstering them and improving their chances of success. An ally must listen to and observe the Charismatic Hero for a full round for the greater inspiration to take hold, and the hero must make a Charisma check (DC 10). The effect lasts for a number of rounds equal to the hero’s Charisma modifier. An inspired ally gains an additional +1 morale bonus on saving throws, attack rolls, and damage rolls, which stacks with the bonus from Inspiration for a total of a +3 morale bonus. A Charismatic Hero can’t inspire themselves. The hero can inspire a number of allies equal to one-half their Charismatic level, rounded down (to a minimum of one ally).'},
  {n:'Inspiring Aura',family:'Charismatic Hero — Leadership Tree',hero_class:'Charismatic Hero',tree:'Leadership Tree',tier:'Super-Talent',prereqs:[[{type:'talent',name:'Coordinate'}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:3}]],prereqs_text:'Coordinate, Supernatural Mutation, 3 MP',mp_cost:3,d:'The Charismatic Hero with Inspiring Aura has a bolstering presence that always gives allies within 30’ a +1 bonus to their attack rolls and skill checks. When the character uses their ability to Coordinate, they can Coordinate a number of allies equal to their Charisma modifier (minimum 1 ally), giving an additional +1 bonus to attack rolls and skill checks that stacks with this one. If the character has Inspiration, then the ability can be used as a standard action. If the character has Greater Inspiration, then the additional bonus applied is +2, for a net morale bonus of +4 to the ally’s saving throws, attack rolls, and damage rolls when using Greater Inspiration.'},
  {n:'Karmic Crusader',family:'Charismatic Hero — Apex: Charismatic Super-Talent',hero_class:'Charismatic Hero',tree:'Apex: Charismatic Super-Talent',tier:'Apex Super-Talent',is_apex:true,prereqs:[[{type:'talentAny',names:['Animal Magnetism','Silver Tongue','Inspiring Aura'],count:2}],[{type:'feat',name:'Supernatural Mutation'}],[{type:'mp',amount:11}]],prereqs_text:'Two of Animal Magnetism, Silver Tongue, and/or Inspiring Aura, Supernatural Mutation, 11 MP',mp_cost:11,d:'The Charismatic Super-Hero, when required to roll a d20, rolls 2d20, taking the desired result.'},
];

// STARTING OCCUPATION DATABASE — v8.2.1: 32 occupations hand-extracted from
// the DxD20 Hero's Handbook, Chapter III (pp. 34-43).
//
// Each occupation grants:
//   - A skill choice: pick N skills from skill_list to designate as permanent
//     class skills. If a picked skill is ALREADY a class skill via another
//     route (any class on the character), it instead grants a +1 competence
//     bonus on checks with that skill.
//   - Optionally, a bonus feat picked from bonus_feat_options.
//   - A Wealth Bonus modifier (and rarely a Reputation modifier).
//
// Entry shape: {n, prereq_age?, prereq_other?, skill_count, skill_list,
//               bonus_feat_options?, wealth?, reputation?, d}
//
// Compound skill entries like 'Knowledge (Arcane Lore, Streetwise, Tactics)'
// represent a choice: when picked, the player selects ONE of the listed
// sub-skills as their class-skill slot. v8.2.1 stores the player's choice as
// the compound string verbatim; sub-skill picking is deferred to a later
// polish pass when needed for aggregator integration.
